/**
 * Iconos CALCADOS de las maquetas de Jorge (2 nov 2026): Mi mascota, Inicio y Tienda.
 * Se recortaron de las imágenes y se vectorizaron con potrace (ryzen-casa:~/calcar/calcar.py),
 * así que la forma es la de la maqueta. `size` es la altura en px; el ancho sale de la proporción.
 * `color` sustituye al color calcado (las capas de otro color, como el collar del perrito, se quedan).
 */
import React from 'react';

type P = { size?: number; color?: string; style?: React.CSSProperties; className?: string; title?: string };

function svg(viewBox: string, g: string, colorPorDefecto: string, altoPorDefecto: number) {
  const [, , w, h] = viewBox.split(/\s+/).map(Number);
  return function Icono({ size = altoPorDefecto, color = colorPorDefecto, style, className, title }: P) {
    return (
      <svg width={(size * w) / h} height={size} viewBox={viewBox} aria-hidden={!title} role={title ? 'img' : undefined} className={className}
        style={{ color, flexShrink: 0, display: 'inline-block', ...style }} dangerouslySetInnerHTML={{ __html: (title ? `<title>${title}</title>` : '') + g }} />
    );
  };
}

